import math

def solution(input_str):
    n, l, r = map(int, input_str.strip().split())

    if n == 1:
        return str(r - l + 1) + '\n'

    if n == 2:
        return str((r - l + 1) * (r - l)) + '\n'

    ans = 0

    # Enumerate all possible ratios p/q in simplest form where p < q
    # Bound: p, q must be at most r since they represent ratios between terms
    max_val = r

    for q in range(2, int(math.sqrt(max_val)) + 2):
        for p in range(1, q):
            if math.gcd(p, q) != 1:
                continue

            ratio_exp = n - 1

            # For d = p/q < 1, progression decreases:
            # a1 * (q/p)^(n-1) <= r  and  a1 >= l
            # We need a1 to be multiple of q^(n-1)

            try:
                q_power = q ** ratio_exp
                p_power_div = p ** ratio_exp
            except OverflowError:
                break

            if p_power_div > r * 10:
                continue

            # a1 = k * q^(n-1), need k * q^(n-1) * (p/q)^(n-1) >= l
            # and k * q^(n-1) <= r

            denom = ratio_exp
            if q_power > max_val or p_power_div > max_val:
                continue

            min_k_from_lower = (l * p_power_div) // q_power + (1 if (l * p_power_div) % q_power != 0 else 0)
            max_k_from_upper = r // q_power

            if min_k_from_lower <= max_k_from_upper:
                cnt = max_k_from_upper - min_k_from_lower + 1
                if cnt > 0:
                    ans += cnt

            # For d = p/q > 1, progression increases
            if p > q:
                try:
                    q_power = q ** ratio_exp
                    p_power = p ** ratio_exp
                except OverflowError:
                    pass
                else:
                    if p_power_div > max_val or q_power > max_val:
                        continue

                    # a1 * (p/q)^(n-1) <= r and a1 >= l
                    # a1 = k * q^(n-1)

