    periods = []
    current_period = []

    for event in events:
        if not event.strip():
            continue
        parts = event.strip().split()
        if parts[0] == '1':
            if current_period:
                periods.append(current_period)
                current_period = []
        else:
            current_period.append(parts[1])
    if current_period:
        periods.append(current_period)

    # Get unique friends
    all_friends = set()
    for period in periods:
        all_friends.update(period)

    friends = sorted(list(all_friends))
    friend_to_idx = {name: i for i, name in enumerate(friends)}
    n_friends = len(friends)

    if n_friends == 0:
        return '0'

    # Build conflict graph (adjacency matrix)
    # adj[i][j] = True if friends i and j cannot both be happy
    adj = [[False] * n_friends for _ in range(n_friends)]
    for period in periods:
        present = [friend_to_idx[name] for name in period if name in friend_to_idx]
        for i in range(len(present)):
            for j in range(i + 1, len(present)):
                adj[present[i]][present[j]] = True
                adj[present[j]][present[i]] = True

    # Find maximum independent set using branch and bound with bitmasks
    best = 0

    def backtrack(mask, count):
        nonlocal best
        best = max(best, count)

        remaining = n_friends - bin(mask).count('1')
        if count + remaining <= best:
            return

        for i in range(n_friends):
            if not (mask & (1 << i)):
                # Check if adding friend i is valid (no conflict with already selected)
                valid = True
                for j in range(n_friends):
                    if (mask >> j) & 1:  # if friend j is already selected
                        if adj[i][j]:
                            valid = False
                            break
                if valid:
                    backtrack(mask | (1 << i), count + 1)

    backtrack(0, 0)
    return str(best)
