    def normalize(a, b):
        # Ensure clockwise from min to max along ring
        if (b - a + n) % n < (a - b + n) % n:
            # b is clockwise from a
            return min(a, b), max(a, b)
        else:
            return min(a, b), max(a, b)

    def crossroad(i, j):
        a1, b1 = normalize(roads[i][0], roads[i][1])
        a2, b2 = normalize(roads[j][0], roads[j][1])

        if a1 == a2 or a1 == b2 or b1 == a2 or b1 == b2:
            return False

        between = lambda x, i, j: (x > i and x < j)
        if between(a2, a1, b1) != between(b2, a1, b1):
            return True
        return False

    adj = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if crossroad(i, j):
                adj[i].append(j)
                adj[j].append(i)

    color = [-1] * m
    try:
        for i in range(m):
            if color[i] == -1:
                color[i] = 0
                stack = [(i, 0)]
                while stack:
                    node, c = stack.pop()
                    color[node] = c
                    for nxt in adj[node]:
                        if color[nxt] == -1:
                            color[nxt] = 1 - c
                            stack.append((nxt, 1 - c))
