        """Check if a sequence is a geometric progression."""
        n_seq = len(seq)
        if n_seq <= 2:
            return True

        # If all zeros, it's a valid GP
        if all(x == 0 for x in seq):
            return True

        # If first element is zero, either all must be zero or it's not a GP
        if seq[0] == 0:
            return False

        # Calculate ratio from first two elements
        ratio_num = seq[1]
        ratio_den = seq[0]

        # Check if all consecutive ratios match
        for i in range(n_seq - 1):
            if seq[i+1] * ratio_den != seq[i] * ratio_num:
                return False

        return True

    # Check if already a GP
    if is_gp(arr):
        return '0\n'

    # Try deleting each element
    for i in range(len(arr)):
        new_arr = arr[:i] + arr[i+1:]
        if is_gp(new_arr):
            return '1\n'

