# Function to memoized OEIS A103627 - number of partitions of n into distinct Fibonacci numbers
from functools import lru_cache

def count_decompositions(n):
    @lru_cache(maxsize=None)
    def dp(k, rem):
        # k is the index of the largest Fibonacci number we can use
        # rem is the remaining amount
        if rem == 0:
            return 1
        if k < 0 or fib[k] > rem:
            return 0

        # Either use fib[k] or don't use fib[k]
        return dp(k - 1, rem - fib[k]) + dp(k - 1, rem)

    return dp(len(fib) - 1, n)

